class Solution {
public:
    int minReorder(int n, vector<vector<int>>& connections) {
        vector<vector<pair<int, int>>> adj(n);
        for (auto& c : connections) {
            adj[c[0]].push_back({c[1], 1});
            adj[c[1]].push_back({c[0], 0});
        }
        vector<int> seen(n, 0);
        stack<int> st;
        st.push(0);
        seen[0] = 2;
        int flips = 0;
        while (!st.empty()) {
            int u = st.top();
            st.pop();
            for (auto& [v, away] : adj[u]) {
                if (seen[v]) continue;
                seen[v] = 2;
                flips += away;
                st.push(v);
            }
        }
        return flips;
    }
};
